As you can see, with multiple threads, there is a race condition and all threads end up
initializing the data. We can avoid this race condition by modifying the program as follows:
static Data _data;
static bool _initialized;
static object _locker = new object();
static void Initializer()
{
Console.WriteLine("Task with id {0}", Task.CurrentId);
LazyInitializer.EnsureInitialized(ref _data,ref _initialized,
ref _locker, () =>
{
Console.WriteLine($"Task with id {Task.CurrentId} is
Initializing data");
// Returns value that will be assigned in the ref parameter.
return new Data();
});
}
public static void Main()
{
Parallel.For(0, 10, (i) => Initializer());
Console.ReadLine();
}
